WITH metrics AS (SELECT id, order_id, cost, FIRST_VALUE(carrier, TRUE) OVER (PARTITION BY status ORDER BY delivered_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_carrier, SUM(cost) OVER (PARTITION BY order_id, status ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_cost, ROUND(cost / SUM(cost) OVER (PARTITION BY MONTH(delivered_date), status), 4) cost_share FROM shipments WHERE carrier != 'FedEx') SELECT s.id, s.order_id, s.cost_share, (SELECT AVG(t2.cost) FROM shipments t2 WHERE t2.order_id = s.order_id) AS avg_shipment_cost FROM metrics s ORDER BY avg_shipment_cost NULLS FIRST
